INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 0.0, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 4, 24015, 24, 4, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 0.0, 110501, 1);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 4.0, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 4, 24016, 24, 1, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 0.0, 110501, 2);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 0.0, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 4, 24017, 24, 4, "マジムンだらけで目が回るさ～！\nふらふらさ～！", 0.0, 110501, 3);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 5.2, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 1, 24018, 24, 2, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 0.0, 110501, 4);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 4.2, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 5, 24019, 24, 6, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 0.0, 110501, 5);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 0.0, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 2, 24020, 24, 2, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 0.0, 110501, 6);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 6.4, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 1, 24021, 24, 6, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 0.0, 110501, 7);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 0.0, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 2, 24022, 24, 2, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 0.0, 110501, 8);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 10.08, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 6, 24023, 24, 3, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 0.0, 110501, 9);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 5.0, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 1, 24024, 24, 2, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 0.0, 110501, 10);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 10021, 0.0, "2030/12/17 14:59:59", 0.0, "カオリ（サマー）", 2, 24025, 24, 2, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 0.0, 110501, 11);
